import { InstallStepId } from "./events";
import type { InstallEstimates } from "./estimates";

/**
 * install.sh's copy of the estimate table (`core/estimates.json`): a bash
 * function between two marker lines, generated by `./equin installer
 * estimates` and held equal to the JSON by the `installer:estimates-in-sync`
 * check. install.sh runs before anything of the repo is on disk (`curl |
 * bash`), so it carries the medians itself rather than reading the JSON.
 */
export const ESTIMATES_BEGIN =
  "# BEGIN estimates — generated by `./equin installer estimates` from plugins/installer/core/estimates.json; do not edit";
export const ESTIMATES_END = "# END estimates";

/** The block's text, both marker lines included, for `estimates`. */
export function renderEstimatesBlock(estimates: InstallEstimates): string {
  return [
    ESTIMATES_BEGIN,
    "est_s() {",
    '  case "$1" in',
    ...InstallStepId.options.map(
      (id) => `    ${id}) echo ${estimates.steps[id] ?? "null"} ;;`,
    ),
    `    *) echo "install.sh: no estimate entry for step '$1'" >&2; exit 2 ;;`,
    "  esac",
    "}",
    ESTIMATES_END,
  ].join("\n");
}

/**
 * The block as install.sh holds it, or why it cannot be found: exactly one
 * begin marker, followed by one end marker.
 */
export function findEstimatesBlock(
  script: string,
):
  | { ok: true; start: number; end: number; text: string }
  | { ok: false; error: string } {
  const start = script.indexOf(ESTIMATES_BEGIN);
  if (start === -1 || script.indexOf(ESTIMATES_BEGIN, start + 1) !== -1)
    return {
      ok: false,
      error: `install.sh must hold the line "${ESTIMATES_BEGIN}" exactly once`,
    };
  const endAt = script.indexOf(ESTIMATES_END, start);
  if (endAt === -1)
    return {
      ok: false,
      error: `install.sh has no "${ESTIMATES_END}" after its estimates block`,
    };
  const end = endAt + ESTIMATES_END.length;
  return { ok: true, start, end, text: script.slice(start, end) };
}
